-- =====================================================================
-- Smart Clinic - Orthodontics module (MySQL 8 / MariaDB 10.3+)
--
-- Run in EACH CLINIC (tenant) database - NOT in the central database.
-- Preferred instead: php artisan tenants:migrate   (same result, all clinics)
--
-- This file equals the three tenant migrations:
--   2026_11_14_000001_add_enable_orthodontics_setting
--   2026_11_14_000002_add_orthodontics_permissions
--   2026_11_14_000003_create_orthodontics_tables
-- The CREATE TABLE statements were generated by Laravel's own MySQL schema
-- grammar from the migration, so they match what the migration creates.
--
-- Sections 1, 2 and 4 are safe to run more than once. Section 3 (tables)
-- runs once per clinic database: it stops with "table already exists" if
-- the module is already installed there.
--
-- After running it, clear the permission cache:
--   php artisan cache:clear        (or wait for the cache to expire)
-- =====================================================================

SET NAMES utf8mb4;

-- ---------------------------------------------------------------------
-- 1. Clinic setting: module switch (OFF by default, never overwritten)
-- ---------------------------------------------------------------------
INSERT INTO `clinic_settings` (`setting_key`, `setting_value`, `setting_type`, `description`, `is_active`, `created_at`, `updated_at`)
SELECT 'enable_orthodontics', '0', 'boolean',
       'Orthodontics module: cephalometric, 3D model, CBCT and facial analysis tools inside orthodontic cases',
       1, NOW(), NOW()
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `clinic_settings` WHERE `setting_key` = 'enable_orthodontics');

-- To switch the module ON for this clinic (normally done from Settings):
-- UPDATE `clinic_settings` SET `setting_value` = '1', `updated_at` = NOW() WHERE `setting_key` = 'enable_orthodontics';

-- ---------------------------------------------------------------------
-- 2. Permissions (spatie/laravel-permission) and role grants
--    super_admin, clinic_super_doctor, doctor get both; secretaries none.
-- ---------------------------------------------------------------------
INSERT INTO `permissions` (`name`, `guard_name`, `created_at`, `updated_at`)
SELECT 'view-orthodontics', 'web', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `permissions` WHERE `name` = 'view-orthodontics' AND `guard_name` = 'web');

INSERT INTO `permissions` (`name`, `guard_name`, `created_at`, `updated_at`)
SELECT 'manage-orthodontics', 'web', NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `permissions` WHERE `name` = 'manage-orthodontics' AND `guard_name` = 'web');

INSERT INTO `role_has_permissions` (`permission_id`, `role_id`)
SELECT p.`id`, r.`id`
FROM `permissions` p
JOIN `roles` r ON r.`guard_name` = 'web' AND r.`name` IN ('super_admin', 'clinic_super_doctor', 'doctor')
WHERE p.`guard_name` = 'web'
  AND p.`name` IN ('view-orthodontics', 'manage-orthodontics')
  AND NOT EXISTS (
      SELECT 1 FROM `role_has_permissions` x
      WHERE x.`permission_id` = p.`id` AND x.`role_id` = r.`id`
  );

-- ---------------------------------------------------------------------
-- 3. Tables (run once per clinic database)
--    Case foreign keys are ON DELETE RESTRICT: a hard delete of a case
--    must never silently drop medical records (cases are soft-deleted).
-- ---------------------------------------------------------------------
create table `orthodontic_files` (`id` bigint unsigned not null auto_increment primary key, `case_id` bigint unsigned not null, `kind` varchar(40) not null, `disk` varchar(40) not null, `path` varchar(255) not null, `original_name` varchar(255) null, `mime_type` varchar(120) null, `extension` varchar(16) null, `size` bigint unsigned not null default '0', `sha256` char(64) null, `width` int unsigned null, `height` int unsigned null, `meta` json null, `uploaded_by` bigint unsigned null, `deleted_at` timestamp null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `orthodontic_files` add constraint `orthodontic_files_case_id_foreign` foreign key (`case_id`) references `cases` (`id`) on delete restrict;
alter table `orthodontic_files` add index `orthodontic_files_case_id_kind_index`(`case_id`, `kind`);

create table `orthodontic_cbct_studies` (`id` bigint unsigned not null auto_increment primary key, `case_id` bigint unsigned not null, `driver` varchar(20) not null, `status` varchar(20) not null default 'uploading', `description` varchar(255) null, `study_instance_uid` varchar(128) null, `orthanc_study_id` varchar(64) null, `modality` varchar(16) null, `study_date` date null, `instances_count` int unsigned not null default '0', `total_size` bigint unsigned not null default '0', `series` json null, `viewer_state` json null, `error` text null, `uploaded_by` bigint unsigned null, `completed_at` timestamp null, `deleted_at` timestamp null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `orthodontic_cbct_studies` add constraint `orthodontic_cbct_studies_case_id_foreign` foreign key (`case_id`) references `cases` (`id`) on delete restrict;
alter table `orthodontic_cbct_studies` add index `orthodontic_cbct_studies_case_id_status_index`(`case_id`, `status`);

create table `orthodontic_cbct_instances` (`id` bigint unsigned not null auto_increment primary key, `study_id` bigint unsigned not null, `sop_instance_uid` varchar(128) not null, `series_instance_uid` varchar(128) null, `instance_number` int null, `frames` int unsigned not null default '1', `rows` int unsigned null, `columns` int unsigned null, `slice_position` double null, `path` varchar(255) null, `orthanc_instance_id` varchar(64) null, `size` bigint unsigned not null default '0', `sha256` char(64) null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `orthodontic_cbct_instances` add constraint `orthodontic_cbct_instances_study_id_foreign` foreign key (`study_id`) references `orthodontic_cbct_studies` (`id`) on delete cascade;
alter table `orthodontic_cbct_instances` add unique `orthodontic_cbct_instances_study_id_sop_instance_uid_unique`(`study_id`, `sop_instance_uid`);
alter table `orthodontic_cbct_instances` add index `orthodontic_cbct_instances_study_id_series_instance_uid_index`(`study_id`, `series_instance_uid`);

create table `orthodontic_analyses` (`id` bigint unsigned not null auto_increment primary key, `case_id` bigint unsigned not null, `type` varchar(20) not null, `title` varchar(255) null, `file_id` bigint unsigned null, `cbct_study_id` bigint unsigned null, `analysis_date` date null, `status` varchar(20) not null default 'draft', `revision` int unsigned not null default '1', `data` json null, `results` json null, `notes` text null, `created_by` bigint unsigned null, `updated_by` bigint unsigned null, `reviewed_by` bigint unsigned null, `reviewed_at` timestamp null, `deleted_at` timestamp null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `orthodontic_analyses` add constraint `orthodontic_analyses_case_id_foreign` foreign key (`case_id`) references `cases` (`id`) on delete restrict;
alter table `orthodontic_analyses` add constraint `orthodontic_analyses_file_id_foreign` foreign key (`file_id`) references `orthodontic_files` (`id`) on delete set null;
alter table `orthodontic_analyses` add constraint `orthodontic_analyses_cbct_study_id_foreign` foreign key (`cbct_study_id`) references `orthodontic_cbct_studies` (`id`) on delete set null;
alter table `orthodontic_analyses` add index `orthodontic_analyses_case_id_type_index`(`case_id`, `type`);

create table `orthodontic_analysis_revisions` (`id` bigint unsigned not null auto_increment primary key, `analysis_id` bigint unsigned not null, `revision` int unsigned not null, `status` varchar(20) not null, `data` json null, `results` json null, `notes` text null, `created_by` bigint unsigned null, `created_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `orthodontic_analysis_revisions` add constraint `orthodontic_analysis_revisions_analysis_id_foreign` foreign key (`analysis_id`) references `orthodontic_analyses` (`id`) on delete cascade;
alter table `orthodontic_analysis_revisions` add unique `orthodontic_analysis_revisions_analysis_id_revision_unique`(`analysis_id`, `revision`);

create table `orthodontic_treatment_plans` (`id` bigint unsigned not null auto_increment primary key, `case_id` bigint unsigned not null, `chief_complaint` text null, `clinical_examination` text null, `diagnosis` text null, `skeletal_class` varchar(20) null, `molar_class_right` varchar(20) null, `molar_class_left` varchar(20) null, `canine_class_right` varchar(20) null, `canine_class_left` varchar(20) null, `crowding_upper_mm` decimal(6, 2) null, `crowding_lower_mm` decimal(6, 2) null, `overjet_mm` decimal(6, 2) null, `overbite_mm` decimal(6, 2) null, `crossbite` varchar(255) null, `midline_upper_mm` decimal(6, 2) null, `midline_lower_mm` decimal(6, 2) null, `observations` json null, `objectives` text null, `planned_treatment` text null, `appliance_type` varchar(255) null, `estimated_duration_months` smallint unsigned null, `stages` json null, `doctor_notes` text null, `start_date` date null, `status` varchar(20) not null default 'planned', `revision` int unsigned not null default '1', `created_by` bigint unsigned null, `updated_by` bigint unsigned null, `deleted_at` timestamp null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `orthodontic_treatment_plans` add constraint `orthodontic_treatment_plans_case_id_foreign` foreign key (`case_id`) references `cases` (`id`) on delete restrict;
alter table `orthodontic_treatment_plans` add unique `orthodontic_treatment_plans_case_id_unique`(`case_id`);

create table `orthodontic_audit_logs` (`id` bigint unsigned not null auto_increment primary key, `case_id` bigint unsigned null, `user_id` bigint unsigned null, `action` varchar(60) not null, `subject_type` varchar(60) null, `subject_id` bigint unsigned null, `details` json null, `ip` varchar(45) null, `created_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `orthodontic_audit_logs` add index `orthodontic_audit_logs_case_id_created_at_index`(`case_id`, `created_at`);
alter table `orthodontic_audit_logs` add index `orthodontic_audit_logs_subject_type_subject_id_index`(`subject_type`, `subject_id`);

-- ---------------------------------------------------------------------
-- 4. Record the migrations, so "php artisan tenants:migrate" does not try
--    to run them again on this database.
-- ---------------------------------------------------------------------
SET @ortho_batch := (SELECT COALESCE(MAX(`batch`), 0) + 1 FROM `migrations`);

INSERT INTO `migrations` (`migration`, `batch`)
SELECT m.`migration`, @ortho_batch
FROM (
    SELECT '2026_11_14_000001_add_enable_orthodontics_setting' AS `migration`
    UNION ALL SELECT '2026_11_14_000002_add_orthodontics_permissions'
    UNION ALL SELECT '2026_11_14_000003_create_orthodontics_tables'
) m
WHERE NOT EXISTS (SELECT 1 FROM `migrations` x WHERE x.`migration` = m.`migration`);
